INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-26', 'INSURANCE', '종합위험 시설작물 생산비보장', '§5 종합위험 시설작물 손해평가 (대상품목 22 작물 + 버섯 6종). 보장 = 보장재해로 사고 발생 시점까지 투입된 작물의 생산비를 피해율에 따라 지급. 산식 (일반) = 피해작물 재배면적 × 피해작물 단위 면적당 보장생산비 × 경과비율 × 피해율. 비례보상 (보험가입금액 < 단위면적당 보장생산비 × 재배면적) 적용. 화재 손해는 자기부담금 미적용.', '종합위험 시설작물 생산비보장', NULL, NULL, 'p.577', 577, 584, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-27', 'INSURANCE', '종합위험 농업용 시설물·부대시설 손해보장', '§5 농업용 시설물(원예시설/단동하우스/연동하우스/광폭형하우스/경량철골조 등) + 부대시설 손해 평가. 보험가입금액 ≥ 보험가액 → 손해액 - 자기부담금 (보험가액 한도). 보험가입금액 < 보험가액 → MIN(손해액 - 자기부담금, 보험가입금액) 비례보상. 재조달가액 보장 특별약관 가입 + 수리복구 시 재조달가액 기준. 자기부담금 = 단지·1사고 단위, 화재 미적용.', '종합위험 농업용 시설물·부대시설 손해보장', NULL, NULL, 'p.579', 579, 586, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-28', 'INSURANCE', '종합위험 버섯재배사·버섯작물 손해보장', '§5 버섯재배사(단동/연동/경량철골조 버섯재배 시설) + 버섯작물 (표고버섯 원목·톱밥배지/느타리버섯 균상·병재배/새송이버섯 병재배/양송이버섯 균상재배). 산식 = 재배(원목/배지/병/면적) × 단위당 보장생산비 × 경과비율 × 피해율. 1사고마다 보험금 10만원 초과 시 전액 보장.', '종합위험 버섯재배사·버섯작물 손해보장', NULL, NULL, 'p.578', 578, 585, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-29', 'INSURANCE', '농업수입감소보장 (일반)', '§6 농업수입안정보험 — 기존 농작물재해보험에 농산물 가격하락을 반영한 농업수입 감소보장. 피해율 = (기준수입 - 실제수입) ÷ 기준수입. 기준수입 = 평년수확량 × 기준가격 (또는 max[기준가격, 수확기가격]). 보험금 산정 = 과거수입형 (보험가입금액 × (피해율 - 자기부담비율)) / 기대수입형 (기준수입 × (피해율 - 자기부담비율)).', '농업수입감소보장', NULL, NULL, 'p.601', 601, 608, '제2편 농작물재해보험 손해평가', '제6절 농업수입감소보장방식의 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-30', 'INSURANCE', '농업수입감소보장 — 포도', '§6-1 과수 (포도) 농업수입감소. 보험금 (도복 보장) = 보험가입금액 × (피해율 × 10%) / 일반 = 보험가입금액 × (피해율 - 자기부담비율). 피해율 = 피해주수(고사된 나무) ÷ 실제결과주수. 착과수조사 + 과중조사 + 낙과피해조사 + 고사주수조사 (포도 4단계 조사).', '농업수입감소보장', NULL, NULL, 'p.602', 602, 609, '제2편 농작물재해보험 손해평가', '제6절 농업수입감소보장방식의 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-31', 'INSURANCE', '농업수입감소보장 — 밭작물 10종', '§6-2 밭작물 [감자(봄/고랭지/가을), 고구마, 콩, 마늘, 양파, 양배추(가을·월동), 옥수수, 배추(고랭지·가을), 고랭지무, 가을무(일반무)]. 종합위험 수확감소보장(INS-21) 의 손해평가 방식 정합 + 수입감소(기준가격/수확기가격) 추가 처리. 재파종/재정식/경작불능/수확량조사 동일 + 농업수입감소보험금 산정.', '농업수입감소보장', NULL, NULL, 'p.620', 620, 627, '제2편 농작물재해보험 손해평가', '제6절 농업수입감소보장방식의 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-32', 'INSURANCE', '농업수입감소보장 — 벼', '§6-3 벼 농업수입감소. 손해평가 = INS-15(논작물 수확감소보장) 정합 + 수입감소 추가. 손해액 (기준가격 ≥ 수확기가격) = (기준가격 - 수확기가격) × (평년수확량 - 피해수확량) / 손해액 (대안) = 기준가격 × 피해수확량. 이앙·직파불능/재이앙·재직파/경작불능 조사 + 농업수입감소보험금.', '농업수입감소보장', NULL, NULL, 'p.634', 634, 641, '제2편 농작물재해보험 손해평가', '제6절 농업수입감소보장방식의 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-060', 'CROP', '시설오이 (시설재배)', '§5 종합위험 시설작물 생산비보장 대상. 산식 = 재배면적 × 단위면적당 보장생산비 × 경과비율 × 피해율. 피해율 = 피해비율 × 손해정도비율 × (1-미보상비율).', '종합위험 시설작물 생산비보장', '시설오이', NULL, 'p.588', 588, 595, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 7, 'draft');
