INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-082', 'CROP', '시설감자 (시설재배)', '§5 종합위험 시설작물 생산비보장 대상. 표준생장일수 110일, 표준수확일수 9일. 9~11월 정식 + 겨울 + 3월 이후 수확 종료 시 적용.', '종합위험 시설작물 생산비보장', '시설감자', NULL, 'p.594', 594, 601, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-083', 'CROP', '표고버섯(원목재배)', '§5 종합위험 버섯작물 손해보장. 산식 = 재배원목수 × 원목당 보장생산비 × 피해율 (경과비율 X). 피해비율 = 피해원목수 ÷ 재배원목수. 손해정도비율 = 원목 피해면적 ÷ 원목면적. 표본원목수표 (1,000본 이하 10본 → 2,300본 초과 26본).', '종합위험 버섯재배사·버섯작물 손해보장', '표고버섯(원목재배)', NULL, 'p.594', 594, 601, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-084', 'CROP', '표고버섯(톱밥배지재배)', '§5 종합위험 버섯작물 손해보장. 산식 = 재배배지수 × 배지당 보장생산비 × 경과비율 × 피해율. 준비기 생산비 계수 α = 81.4%. 손해정도비율 50%/100% 결정.', '종합위험 버섯재배사·버섯작물 손해보장', '표고버섯(톱밥배지재배)', NULL, 'p.595', 595, 602, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-085', 'CROP', '느타리버섯(균상재배)', '§5 종합위험 버섯작물 손해보장. 산식 = 재배면적 × 단위면적당 보장생산비 × 경과비율 × 피해율. 준비기 생산비 계수 α = 69.7%.', '종합위험 버섯재배사·버섯작물 손해보장', '느타리버섯(균상재배)', NULL, 'p.596', 596, 603, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-086', 'CROP', '느타리버섯(병재배)', '§5 종합위험 버섯작물 손해보장. 산식 = 재배병수 × 병당 보장생산비 × 경과비율 × 피해율. 경과비율 일자 무관 88.7% 일정.', '종합위험 버섯재배사·버섯작물 손해보장', '느타리버섯(병재배)', NULL, 'p.597', 597, 604, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-087', 'CROP', '새송이버섯(병재배)', '§5 종합위험 버섯작물 손해보장. 산식 = 재배병수 × 병당 보장생산비 × 경과비율 × 피해율. 경과비율 일자 무관 91.7% 일정.', '종합위험 버섯재배사·버섯작물 손해보장', '새송이버섯(병재배)', NULL, 'p.598', 598, 605, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-088', 'CROP', '양송이버섯(균상재배)', '§5 종합위험 버섯작물 손해보장. 산식 = 재배면적 × 단위면적당 보장생산비 × 경과비율 × 피해율. 준비기 생산비 계수 α = 70.3%.', '종합위험 버섯재배사·버섯작물 손해보장', '양송이버섯(균상재배)', NULL, 'p.599', 599, 606, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-089', 'CROP', '농업용 시설물 (단동·연동·광폭형 하우스 / 경량철골조)', '§5 종합위험 농업용 시설물 손해보장 대상. 시설 자체 (구조체·피복재). 손해 산정 = 단위면적당 시설가액표 + 파손 칸수·정도 + 감가상각(월 단위). 재조달가액 보장 특별약관 가입 + 수리복구 시 재조달가액 기준.', '종합위험 농업용 시설물·부대시설 손해보장', '농업용 시설물', NULL, 'p.579', 579, 586, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-090', 'CROP', '포도 (농업수입감소)', '§6-1 농업수입감소보장 — 포도. 보험금 (도복특수) = 보험가입금액 × (피해율 × 10%) / 일반 = 보험가입금액 × (피해율 - 자기부담비율). 피해율 = 피해주수(고사된 나무) ÷ 실제결과주수. 4단계 조사 (착과수/과중/낙과피해/고사주수).', '농업수입감소보장', '포도', NULL, 'p.602', 602, 609, '제2편 농작물재해보험 손해평가', '제6절 농업수입감소보장방식의 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-073', 'INVESTIGATION', '인삼 수확량조사', 'INS-23 작물특정 인삼손해보장. 전수조사 또는 표본조사. (1) 전체 칸수 및 칸 넓이 조사 — 칸 넓이 = 지주목 간격 × (두둑 폭 + 고랑 폭). (2) 전수조사 = 금번 수확칸수 + 미수확칸수 + 기수확칸수 + 실 수확량(인삼 무게). (3) 표본조사 = 정상 칸수 + 피해 칸수 + 피해칸수에 따른 적정 표본칸수 + 표본칸 내 인삼 모두 수확 후 무게.', '작물특정 인삼손해보장', NULL, '수확량조사', 'p.570', 570, 577, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-074', 'INVESTIGATION', '인삼 해가림시설 손해조사', 'INS-24 시설(해가림시설) 종합위험 손해보장. 사고접수 직후. (1) 보장재해 여부 + (2) 전체 칸수 및 칸 넓이 조사 + (3) 손해액 산정 (단위면적당 시설가액표 × 파손 칸수·정도 × 감가율). 인삼 해가림시설 감가율 = 목재 6년 13.33% / 철재 18년 4.44%. 피해액 < 보험가액 20% → 감가 미적용. 피해액 ≥ 20% + 감가 후 < 20% → 보험가액 20% 손해액. 재조달가액 특약 적용 시 재조달가액 기준 (수리복구 미시 시가).', '시설(해가림시설) 종합위험 손해보장', NULL, '해가림시설 손해조사', 'p.571', 571, 578, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-075', 'INVESTIGATION', '농업용 시설물·부대시설 손해조사', 'INS-27 적용. 사고 접수 직후 실시. 손상된 골조 재사용 가능 여부 → 전체 교체 / 부분 교체 / 부분 보수 결정. 인건비 산정 = 실제 투입 인력 + 시방서 + 견적서 + 영수증 + 시장조사. 자기부담금 = 단지 단위 + 1사고 단위. 화재 손해는 자기부담금 미적용.', '종합위험 농업용 시설물·부대시설 손해보장', NULL, '농업용 시설물 손해조사', 'p.579', 579, 586, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-076', 'INVESTIGATION', '시설작물 손해조사', 'INS-26 적용. 재배일정 확인(정식·파종·종균접종일·수확개시·수확종료일). 손해정도비율 — 보험목적물의 뿌리·줄기·잎·과실 손해 정도에 따른 손해정도비율(별표6, 26년 신규 10단계). 잔존물 제거비용은 손해액의 10% 한도.', '종합위험 시설작물 생산비보장', NULL, '시설작물 손해조사', 'p.583', 583, 590, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-077', 'INVESTIGATION', '버섯 표본조사 (원목/배지/병/면적)', 'INS-28 적용. 표본원목수표 (1,000본 이하 10본 / 1,300본 14본 / 1,500본 16본 / 1,800본 18본 / 2,000본 20본 / 2,300본 24본 / 2,300본 초과 26본). 손해정도비율 50%/100% (표고/느타리 톱밥배지) 또는 별표6 10단계 (느타리·새송이·양송이 균상·병재배).', '종합위험 버섯재배사·버섯작물 손해보장', NULL, '버섯 표본조사', 'p.595', 595, 602, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-078', 'INVESTIGATION', '포도 농업수입감소 4단계 조사 (착과수/과중/낙과피해/고사주수)', 'INS-30 포도 농업수입감소. (1) 착과수조사 — 표본주수 산정 + 표본주 내 착과수 + 품종·재배방식·수령별. (2) 과중조사 — 표본 과실 추출(품종별 3주 이상의 평균적 나무) + 과실 분류(피해인정계수표 별표3). (3) 낙과피해조사 — 표본조사 (표본 과실수 품종별 30개 이상). (4) 고사주수조사 — 수확 완료 전 고사주수 (보상하지 않는 손해 = 미보상 주수).', '농업수입감소보장', NULL, '포도 농업수입감소 4단계 조사', 'p.602', 602, 609, '제2편 농작물재해보험 손해평가', '제6절 농업수입감소보장방식의 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-079', 'INVESTIGATION', '농업수입감소 밭작물 손해조사', 'INS-31 적용. 적용 품목 = 감자(봄/고랭지/가을), 고구마, 콩, 마늘, 양파, 양배추(가을·월동), 옥수수, 배추(고랭지·가을), 고랭지무, 가을무(일반무). 마늘·가을무·감자(가을재배) = 종합위험 수확감소보장방식 손해평가 정합. 표본조사 + 콩 전수조사 가능. 수확량조사 재조사 + 검증조사 (2주 이내 미수확 시).', '농업수입감소보장', NULL, '농업수입감소 밭작물 손해조사', 'p.620', 620, 627, '제2편 농작물재해보험 손해평가', '제6절 농업수입감소보장방식의 손해평가 및 보험금 산정', 'BATCH-5', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-080', 'INVESTIGATION', '농업수입감소 벼 손해조사', 'INS-32 적용. 손해평가 = INS-15 논작물 수확감소 정합 + 수입감소 추가. 예찰조사 + 피해사실 확인 + 이앙·직파불능(이앙한계일 7월 31일 이후) + 재이앙·재직파 + 경작불능(식물체 피해율 65% 이상) + 수확량조사. 표본포기 선정 = 재배방법 및 품종 등을 감안하여 동일 간격 골고루 배치.', '농업수입감소보장', NULL, '농업수입감소 벼 손해조사', 'p.634', 634, 641, '제2편 농작물재해보험 손해평가', '제6절 농업수입감소보장방식의 손해평가 및 보험금 산정', 'BATCH-5', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-099', 'CONCEPT', '연근별 기준수확량 (인삼)', 'INS-23 인삼손해보장 피해율 산식의 핵심 변수. 가입 당시 년근 기준 (단위 kg/m²) — 2년근 우수 0.55/표준 0.50/불량 0.45 / 3년근 0.70/0.64/0.57 / 4년근 0.78/0.71/0.64 / 5년근 0.81/0.73/0.66.', '작물특정 인삼손해보장', NULL, NULL, 'p.574', 574, 581, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-100', 'CONCEPT', '칸 넓이 / 칸수 (인삼)', 'INS-23 인삼·해가림시설 조사의 단위. 칸 넓이 = 지주목 간격 × (두둑 폭 + 고랑 폭). 전체 칸수 = 농지 내 경작 칸수 (직접 세거나 경작면적 ÷ 칸 넓이). 표본칸·피해칸·정상칸 분류 (별표1 표본칸수표).', '작물특정 인삼손해보장', NULL, NULL, 'p.570', 570, 577, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-101', 'CONCEPT', '감가율 / 감가상각 (인삼 해가림시설)', 'INS-24 시설 손해 산정. 인삼 해가림시설 감가율 (월 단위) — 목재 내용연수 6년 / 경년감가율 13.33% / 철재 내용연수 18년 / 경년감가율 4.44%. 경과월수 = 사고연월 - 최초구조체구입연월. 피해액 < 보험가액의 20% → 감가 미적용. 피해액 ≥ 보험가액의 20% + 감가 후 < 20% → 보험가액의 20% 손해액. 재조달가액 보장 특약 + 수리복구 시 재조달가액 기준 / 미수리 시 시가 (감가상각된 금액).', '시설(해가림시설) 종합위험 손해보장', NULL, NULL, 'p.572', 572, 579, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-102', 'CONCEPT', '잔존물 제거비용 / 손해방지비용 / 대위권 보전비용 / 잔존물 보전비용', '비용손해 4종 — 잔존물 제거비용 = 손해액 10% 한도(인삼 작물 잔존물 제거비용 미지급) / 손해방지비용 농지별 20만원 한도 (보험가입금액 초과 가능) / 대위권 보전비용 / 잔존물 보전비용 (재해보험사업자 잔존물 취득 의사표시 + 취득한 경우만). 기타 협력비용 = 보험가입금액 초과 시에도 전액 지급.', '공통', NULL, NULL, 'p.574', 574, 581, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-103', 'CONCEPT', '단위면적당 보장생산비 (시설작물·버섯)', 'INS-26·INS-28 산식의 핵심 변수. 약관 별도 정의 (작물별·재배방식별 다름). 시설작물 일반 = ㎡ 기준. 표고버섯(원목) = 본 기준. 표고버섯(톱밥배지) = 봉 기준. 느타리버섯(병재배)·새송이버섯·느타리버섯(균상)·양송이버섯 = 병/㎡ 기준.', '종합위험 시설작물 생산비보장', NULL, NULL, 'p.588', 588, 595, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-104', 'CONCEPT', '시설작물·버섯 표준생장일수 / 표준수확일수 / 준비기생산비계수', 'INS-26·INS-28 경과비율 (수확기 이전) 산식의 변수. 시설국화 스탠다드형 120일/스프레이형 90일 / 시설가지 50일·262일 / 시설배추 70일·50일 / 시설대파 120일·64일 / 시설쪽파 60일·19일 / 시설무 일반 80일·28일·기타 50일·28일 / 시설백합 100일·23일 / 시설카네이션 150일·224일 / 시설미나리 130일·88일 / 시설쑥갓 50일·51일 / 시설감자 110일·9일 (9~11월 정식). 버섯 준비기생산비계수 = 표고버섯(톱밥배지) 81.4% / 느타리버섯(균상) 69.7% / 양송이버섯(균상) 70.3%. 느타리버섯(병재배) 일정 88.7% / 새송이버섯 일정 91.7%.', '종합위험 시설작물 생산비보장', NULL, NULL, 'p.594', 594, 601, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-105', 'CONCEPT', '비례보상 (시설·해가림시설)', 'INS-24·INS-26·INS-27 적용. 보험가입금액 < 보험가액(또는 단위면적당 보장생산비 × 재배면적) 시 보험가입금액 한도 비례보상. 비례보상 = 보험가입금액 ÷ 보험가액 (또는 재조달가액). 시설작물 = 재계산 산식 = 위에서 계산된 생산비보장보험금 × 보험가입금액 / (단위면적당 보장생산비 × 재배면적). 손해방지/대위권/잔존물 보전 비용은 비례보상 적용 + 초과보상 모두 적용 (기타 협력비용은 초과보상만).', '종합위험 시설작물 생산비보장', NULL, NULL, 'p.575', 575, 582, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-106', 'CONCEPT', '기준수입 / 실제수입 (농업수입감소)', 'INS-29~32 농업수입감소 피해율 산식의 핵심 변수. 기준수입 = 평년수확량 × 기준가격 / (대안) 평년수확량 × max[기준가격, 수확기가격]. 실제수입 = 수확량 × max[기준가격, 수확기가격] (또는 수확기가격). 농업수입감소 피해율 = (기준수입 - 실제수입) ÷ 기준수입.', '농업수입감소보장', NULL, NULL, 'p.616', 616, 623, '제2편 농작물재해보험 손해평가', '제6절 농업수입감소보장방식의 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-107', 'CONCEPT', '기준가격 / 수확기가격 (농업수입감소)', 'INS-29~32 기준수입·실제수입의 두 변수. 기준가격 = 보험기간 시점에 약관에서 정한 가격 (작물별 기준가격 산정). 수확기가격 = 수확기에 측정한 시장가격. 비교: 기준가격 ≥ 수확기가격 시 수입감소 발생.', '농업수입감소보장', NULL, NULL, 'p.616', 616, 623, '제2편 농작물재해보험 손해평가', '제6절 농업수입감소보장방식의 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-108', 'CONCEPT', '농업수입감소 보험금 산정 (과거수입형 / 기대수입형)', 'INS-29~32 보험금 산정의 두 방식. 과거수입형 = 보험가입금액 × (피해율 - 자기부담비율). 기대수입형 = 기준수입 × (피해율 - 자기부담비율). 작물별·계약별 선택.', '농업수입감소보장', NULL, NULL, 'p.631', 631, 638, '제2편 농작물재해보험 손해평가', '제6절 농업수입감소보장방식의 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-109', 'CONCEPT', '벼 농업수입감소 손해액 산정', 'INS-32 벼 손해액 산식 (2가지). (1) 기준가격 ≥ 수확기가격: 손해액 = (기준가격 - 수확기가격) × (평년수확량 - 피해수확량) / (2) 일반: 손해액 = 기준가격 × 피해수확량.', '농업수입감소보장', NULL, NULL, 'p.633', 633, 640, '제2편 농작물재해보험 손해평가', '제6절 농업수입감소보장방식의 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-110', 'CONCEPT', '포도 4단계 조사 — 표본·과중·낙과·고사', 'INS-30 포도 농업수입감소 손해평가의 4단계 조사. (1) 착과수조사 — 품종·재배방식·수령별 표본주수 산정 + 표본주 내 착과수 + 정해진 값의 1/2 이하 가능. (2) 과중조사 — 표본 과실 추출(품종별 3주 이상 평균적 나무) + 피해인정계수표(별표3) 분류. (3) 낙과피해조사 — 표본조사 (단, 계약자 등이 낙과된 과실을 한 곳에 모아둔 경우는 전수조사). 표본 과실수 = 품종별 30개 이상 (포도·감귤(만감류) 농지당). (4) 고사주수조사 — 수확 완료 전 고사주수 + 보상하지 않는 손해로 고사한 나무 = 미보상 주수.', '농업수입감소보장', NULL, NULL, 'p.604', 604, 611, '제2편 농작물재해보험 손해평가', '제6절 농업수입감소보장방식의 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-111', 'CONCEPT', '재조달가액 (시설·해가림시설)', '보험의 목적과 동형 동질의 신품을 조달하는데 소요되는 금액. 재조달가액 보장 특별약관 가입 시 재조달가액 기준으로 손해액 산출. 보험의 목적이 손해를 입은 장소에서 실제로 수리 또는 복구되지 않은 때에는 재조달가액에 의한 보상을 하지 않고 시가(감가상각된 금액)로 보상.', '시설(해가림시설) 종합위험 손해보장', NULL, NULL, 'p.580', 580, 587, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-112', 'CONCEPT', '표본원목수표 (표고버섯 원목재배)', 'INS-28 표고버섯(원목재배) 손해조사의 표본 산정 표. 피해 원목수 1,000본 이하 → 조사 표본수 10. 1,300본 이하 14. 1,500본 이하 16. 1,800본 이하 18. 2,000본 이하 20. 2,300본 이하 24. 2,300본 초과 26.', '종합위험 버섯재배사·버섯작물 손해보장', NULL, NULL, 'p.595', 595, 602, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-113', 'CONCEPT', '시설·버섯 손해정도비율 / 손해정도비율 50·100% (표고·느타리톱밥)', 'INS-26·28 피해율의 한 변수. 일반 작물·균상재배·병재배 = 별표6 10단계 (1~10%→10%, ..., 91~100%→100%). 표고버섯(톱밥배지)·느타리버섯(톱밥배지) = 50%·100% 2단계 결정. 시설작물 보험목적물 뿌리·줄기·잎·과실 등에 발생한 손해 정도에 따른 손해정도비율 산정.', '종합위험 시설작물 생산비보장', NULL, NULL, 'p.596', 596, 603, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-039', 'TERM', '절화 / 재절화재배 (시설 화훼)', '절화 = 꽃을 자른 상태로 출하. 재절화재배 = 절화를 채취하고 난 뒤 모주에서 곧바로 싹을 키워 절화하는 방법 (시설국화 등 화훼 적용).', '종합위험 시설작물 생산비보장', NULL, NULL, 'p.589', 589, 596, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-040', 'TERM', '종균접종일 (버섯)', 'INS-28 버섯 산식의 시점 용어. 종균접종일로부터 사고발생일까지 = 생장일수. 종균접종일로부터 수확개시일까지 = 표준생장일수. 표고버섯(톱밥배지)·느타리버섯(균상)·양송이버섯(균상) 적용.', '종합위험 버섯재배사·버섯작물 손해보장', NULL, NULL, 'p.595', 595, 602, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-041', 'TERM', '조사대상주수 / 표본주수 (포도)', 'INS-30 포도 농업수입감소. 조사대상주수 = 실제결과주수 - 미보상 주수 - 고사주수. 표본주수 = 조사대상주수에 따라 적정 표본 산정 (별표 — 품종·재배방식·수령별).', '농업수입감소보장', NULL, NULL, 'p.603', 603, 610, '제2편 농작물재해보험 손해평가', '제6절 농업수입감소보장방식의 손해평가 및 보험금 산정', 'BATCH-5', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-042', 'TERM', '단동·연동·광폭형 하우스 / 경량철골조 (농업용 시설물)', 'INS-27 적용 시설물 분류. 단동하우스 (광폭형하우스 포함) = 1동 1골조. 연동하우스 = 다동 연결. 경량철골조 = 강성 강화 시설. 버섯재배사 (단동/연동/경량철골조) 도 동일 분류.', '종합위험 농업용 시설물·부대시설 손해보장', NULL, NULL, 'p.578', 578, 585, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-98', 'FORMULA', '인삼 보험금', '산식: insurance_amount * (damage_rate - deductible_rate)', '작물특정 인삼손해보장', NULL, NULL, 'p.573', 573, 580, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-99', 'FORMULA', '인삼 피해율', '산식: (yield / per_year_reference_yield) * (damage_area / planted_area)', '작물특정 인삼손해보장', NULL, NULL, 'p.573', 573, 580, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-100', 'FORMULA', '인삼 칸 넓이', '산식: pillar_distance * (mound_width + furrow_width)', '작물특정 인삼손해보장', NULL, NULL, 'p.571', 571, 578, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-101', 'FORMULA', '해가림시설 보험금 (보험가입금액 ≥ 보험가액)', '산식: min(insurance_amount, max(0, loss_amount - deductible_amount) * (insurance_amount / actual_value))', '시설(해가림시설) 종합위험 손해보장', NULL, NULL, 'p.575', 575, 582, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-102', 'FORMULA', '해가림시설 보험금 (재조달가액 특약 + 수리복구)', '산식: (loss_amount - deductible_amount) * (insurance_amount / replacement_value)', '시설(해가림시설) 종합위험 손해보장', NULL, NULL, 'p.575', 575, 582, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-103', 'FORMULA', '농업용 시설물 보험금 (보험가입금액 < 보험가액)', '산식: min(loss_amount - deductible_amount, insurance_amount)', '종합위험 농업용 시설물·부대시설 손해보장', NULL, NULL, 'p.585', 585, 592, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-104', 'FORMULA', '시설작물 생산비보장보험금 (일반)', '산식: planted_area * unit_area_guaranteed_production_cost * progress_rate * damage_rate', '종합위험 시설작물 생산비보장', NULL, NULL, 'p.592', 592, 599, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-105', 'FORMULA', '시설작물·버섯 비례보상 재계산', '산식: original_payout * insurance_amount / (unit_guaranteed_production_cost * planted_count)', '종합위험 시설작물 생산비보장', NULL, NULL, 'p.590', 590, 597, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-106', 'FORMULA', '시설작물·버섯 경과비율 (수확기 이전, α 가변)', '산식: alpha + (1 - alpha) * min(growth_days / standard_growth_days, 1.0)', '종합위험 시설작물 생산비보장', NULL, NULL, 'p.595', 595, 602, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-107', 'FORMULA', '시설작물·버섯 경과비율 (수확기 중)', '산식: 1 - (harvest_days / standard_harvest_days)', '종합위험 시설작물 생산비보장', NULL, NULL, 'p.596', 596, 603, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-108', 'FORMULA', '시설작물 피해율', '산식: damage_ratio * damage_severity_rate * (1 - uncovered_ratio)', '종합위험 시설작물 생산비보장', NULL, NULL, 'p.589', 589, 596, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-109', 'FORMULA', '표고버섯(원목재배) 생산비보장보험금', '산식: planted_log_count * unit_log_guaranteed_production_cost * damage_rate', '종합위험 버섯재배사·버섯작물 손해보장', NULL, NULL, 'p.594', 594, 601, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
