INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-123', 'FORMULA', '벼 농업수입감소 손해액 (기준가격 ≥ 수확기가격)', '산식: (reference_price - harvest_period_price) * (reference_yield - damage_yield)', '농업수입감소보장', NULL, NULL, 'p.633', 633, 640, '제2편 농작물재해보험 손해평가', '제6절 농업수입감소보장방식의 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-124', 'FORMULA', '벼 농업수입감소 손해액 (대안)', '산식: reference_price * damage_yield', '농업수입감소보장', NULL, NULL, 'p.633', 633, 640, '제2편 농작물재해보험 손해평가', '제6절 농업수입감소보장방식의 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-125', 'FORMULA', '인삼 단위면적당 조사수확량', '산식: total_yield / harvest_area_at_time', '작물특정 인삼손해보장', NULL, NULL, 'p.574', 574, 581, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-126', 'FORMULA', '인삼 단위면적당 미보상감수량', '산식: (per_year_reference_yield - per_area_actual_yield) * uncovered_ratio', '작물특정 인삼손해보장', NULL, NULL, 'p.574', 574, 581, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-127', 'FORMULA', '인삼 수확량 산정', '산식: per_area_actual_yield + per_area_uncovered_loss', '작물특정 인삼손해보장', NULL, NULL, 'p.574', 574, 581, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-128', 'FORMULA', '해가림시설 자기부담금 (10/100/10%)', '산식: max(min(loss_amount * 0.10, 1000000), 100000)', '시설(해가림시설) 종합위험 손해보장', NULL, NULL, 'p.575', 575, 582, '제2편 농작물재해보험 손해평가', '제4절 밭작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-129', 'FORMULA', '수입감소 자기부담비율별 경작불능보험금 (밭작물)', '산식: insurance_amount * coverage_rate', '농업수입감소보장', NULL, NULL, 'p.630', 630, 637, '제2편 농작물재해보험 손해평가', '제6절 농업수입감소보장방식의 손해평가 및 보험금 산정', 'BATCH-5', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-130', 'FORMULA', '잔존물 제거비용 한도', '산식: min(removal_cost, loss_amount * 0.10)', '공통', NULL, NULL, 'p.585', 585, 592, '제2편 농작물재해보험 손해평가', '제5절 종합위험 시설작물 손해평가 및 보험금 산정', 'BATCH-5', 2026, 7, 'draft');

-- 2. formulas (33 rows, INSERT OR IGNORE — 기존 등록 row 보존)
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-98', '인삼 보험금', 'insurance_amount * (damage_rate - deductible_rate)', '{"insurance_amount":"보험가입금액 number>=0","damage_rate":"피해율(F-99 결과) number 0..1","deductible_rate":"자기부담비율 number 0..1"}', 'p.573', 'F-98', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-99', '인삼 피해율', '(yield / per_year_reference_yield) * (damage_area / planted_area)', '{"yield":"수확량(F-127 결과 — 단위면적당 조사수확량 + 단위면적당 미보상감수량) number>=0","per_year_reference_yield":"연근별 기준수확량(2~5년근 우수/표준/불량 12조합 — CONCEPT-099) number>0","damage_area":"피해면적 number>=0","planted_area":"재배면적 number>0"}', 'p.573', 'F-99', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-100', '인삼 칸 넓이', 'pillar_distance * (mound_width + furrow_width)', '{"pillar_distance":"지주목 간격 number>0","mound_width":"두둑 폭 number>=0","furrow_width":"고랑 폭 number>=0"}', 'p.571', 'F-100', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-101', '해가림시설 보험금 (보험가입금액 ≥ 보험가액)', 'min(insurance_amount, max(0, loss_amount - deductible_amount) * (insurance_amount / actual_value))', '{"insurance_amount":"보험가입금액 number>=0","loss_amount":"손해액 number>=0","deductible_amount":"자기부담금(F-128 결과) number>=0","actual_value":"보험가액 number>0"}', 'p.575', 'F-101', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-102', '해가림시설 보험금 (재조달가액 특약 + 수리복구)', '(loss_amount - deductible_amount) * (insurance_amount / replacement_value)', '{"loss_amount":"손해액 number>=0","deductible_amount":"자기부담금(F-128 결과) number>=0","insurance_amount":"보험가입금액 number>=0","replacement_value":"재조달가액 number>0"}', 'p.575', 'F-102', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-103', '농업용 시설물 보험금 (보험가입금액 < 보험가액)', 'min(loss_amount - deductible_amount, insurance_amount)', '{"loss_amount":"손해액 number>=0","deductible_amount":"자기부담금(시설물 단지·1사고 단위, 화재 미적용) number>=0","insurance_amount":"보험가입금액 number>=0"}', 'p.585', 'F-103', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-104', '시설작물 생산비보장보험금 (일반)', 'planted_area * unit_area_guaranteed_production_cost * progress_rate * damage_rate', '{"planted_area":"피해작물 재배면적 number>=0","unit_area_guaranteed_production_cost":"피해작물 단위면적당 보장생산비(작물별 약관 별도) number>0","progress_rate":"경과비율(F-106 수확기 이전 / F-107 수확기 중) number 0..1","damage_rate":"피해율(F-108 결과) number 0..1"}', 'p.592', 'F-104', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-105', '시설작물·버섯 비례보상 재계산', 'original_payout * insurance_amount / (unit_guaranteed_production_cost * planted_count)', '{"original_payout":"위에서 계산된 생산비보장보험금 number>=0","insurance_amount":"보험가입금액 number>=0","unit_guaranteed_production_cost":"단위(면적/원목/배지/병)당 보장생산비 number>0","planted_count":"재배(면적/원목/배지/병)수 number>0"}', 'p.590', 'F-105', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-106', '시설작물·버섯 경과비율 (수확기 이전, α 가변)', 'alpha + (1 - alpha) * min(growth_days / standard_growth_days, 1.0)', '{"alpha":"준비기 생산비 계수 (작물별: 표고버섯(톱밥배지) 0.814 / 느타리버섯(균상) 0.697 / 양송이버섯(균상) 0.703 / 시설작물 변동 — 약관 정의) number 0..1","growth_days":"생장일수 (정식·종균접종일~사고발생일) integer>=0","standard_growth_days":"표준생장일수 (작물별: 시설국화 스탠다드 120/스프레이 90 / 시설가지 50 / 시설배추 70 / 시설대파 120 / 시설쪽파 60 / 시설무 일반 80·기타 50 / 시설백합 100 / 시설카네이션 150 / 시설미나리 130 / 시설쑥갓 50 / 시설감자 110) integer>0"}', 'p.595', 'F-106', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-107', '시설작물·버섯 경과비율 (수확기 중)', '1 - (harvest_days / standard_harvest_days)', '{"harvest_days":"수확일수 (수확개시일~사고발생일) integer>=0","standard_harvest_days":"표준수확일수 (수확개시일~수확종료일) integer>0"}', 'p.596', 'F-107', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-108', '시설작물 피해율 (시설작물·버섯 균상·병재배)', 'damage_ratio * damage_severity_rate * (1 - uncovered_ratio)', '{"damage_ratio":"피해비율(피해면적÷재배면적 또는 피해병수÷재배병수 등) number 0..1","damage_severity_rate":"손해정도비율 (별표6 — 일반 10단계 / 표고·느타리 톱밥배지 = 50%·100% 2단계) number 0..1","uncovered_ratio":"미보상비율 number 0..1"}', 'p.589', 'F-108', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-109', '표고버섯(원목재배) 생산비보장보험금', 'planted_log_count * unit_log_guaranteed_production_cost * damage_rate', '{"planted_log_count":"재배원목수 integer>=0","unit_log_guaranteed_production_cost":"원목당 보장생산비 (약관 별도) number>0","damage_rate":"피해율(F-108 결과 — 피해비율 = 피해원목수/재배원목수, 손해정도비율 = 원목 피해면적/원목면적) number 0..1"}', 'p.594', 'F-109', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-110', '표고버섯(톱밥배지재배) 생산비보장보험금', 'planted_substrate_count * unit_substrate_guaranteed_production_cost * progress_rate * damage_rate', '{"planted_substrate_count":"재배배지수 integer>=0","unit_substrate_guaranteed_production_cost":"배지당 보장생산비 (약관 별도) number>0","progress_rate":"경과비율(F-106 α=0.814 / F-107) number 0..1","damage_rate":"피해율(F-108 — 손해정도비율 50%·100%) number 0..1"}', 'p.595', 'F-110', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-111', '느타리버섯(균상재배) 생산비보장보험금', 'planted_area * unit_area_guaranteed_production_cost * progress_rate * damage_rate', '{"planted_area":"재배면적(균상면적, ㎡) number>=0","unit_area_guaranteed_production_cost":"단위 면적당 보장생산비 (약관 별도) number>0","progress_rate":"경과비율(F-106 α=0.697 / F-107) number 0..1","damage_rate":"피해율(F-108) number 0..1"}', 'p.596', 'F-111', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-112', '느타리버섯(병재배) 생산비보장보험금', 'planted_bottle_count * unit_bottle_guaranteed_production_cost * 0.887 * damage_rate', '{"planted_bottle_count":"재배병수 integer>=0","unit_bottle_guaranteed_production_cost":"병당 보장생산비 (약관 별도) number>0","damage_rate":"피해율(F-108 — 별표6 10단계) number 0..1"}', 'p.597', 'F-112', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-113', '새송이버섯(병재배) 생산비보장보험금', 'planted_bottle_count * unit_bottle_guaranteed_production_cost * 0.917 * damage_rate', '{"planted_bottle_count":"재배병수 integer>=0","unit_bottle_guaranteed_production_cost":"병당 보장생산비 (약관 별도) number>0","damage_rate":"피해율(F-108 — 별표6 10단계) number 0..1"}', 'p.598', 'F-113', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-114', '양송이버섯(균상재배) 생산비보장보험금', 'planted_area * unit_area_guaranteed_production_cost * progress_rate * damage_rate', '{"planted_area":"재배면적 number>=0","unit_area_guaranteed_production_cost":"단위 면적당 보장생산비 (약관 별도) number>0","progress_rate":"경과비율(F-106 α=0.703 / F-107) number 0..1","damage_rate":"피해율(F-108) number 0..1"}', 'p.599', 'F-114', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-115', '농업수입감소 피해율 (일반)', '(reference_revenue - actual_revenue) / reference_revenue', '{"reference_revenue":"기준수입(F-116 또는 F-117 결과) number>0","actual_revenue":"실제수입 (수확량 × max[기준가격, 수확기가격] 또는 수확기가격) number>=0"}', 'p.616', 'F-115', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-116', '기준수입 (단순)', 'reference_yield * reference_price', '{"reference_yield":"평년수확량 number>0","reference_price":"기준가격 (작물별 약관 정의) number>0"}', 'p.616', 'F-116', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-117', '기준수입 (max(기준가격, 수확기가격) 변형)', 'reference_yield * max(reference_price, harvest_period_price)', '{"reference_yield":"평년수확량 number>0","reference_price":"기준가격 number>0","harvest_period_price":"수확기가격 number>=0"}', 'p.616', 'F-117', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-118', '포도 농업수입감소보험금 (도복특수)', 'insurance_amount * (damage_rate * 0.10)', '{"insurance_amount":"보험가입금액 number>=0","damage_rate":"피해율(F-120 결과 — 고사주수/실제결과주수) number 0..1"}', 'p.617', 'F-118', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-119', '포도 농업수입감소보험금 (일반)', 'insurance_amount * (damage_rate - deductible_rate)', '{"insurance_amount":"보험가입금액 number>=0","damage_rate":"피해율(F-120 결과) number 0..1","deductible_rate":"자기부담비율 number 0..1"}', 'p.617', 'F-119', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-120', '포도 피해율 (고사주수)', 'dead_tree_count / actual_result_tree_count', '{"dead_tree_count":"피해주수(고사된 나무) integer>=0","actual_result_tree_count":"실제결과주수 integer>0"}', 'p.617', 'F-120', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-121', '농업수입감소보험금 (과거수입형)', 'insurance_amount * (damage_rate - deductible_rate)', '{"insurance_amount":"보험가입금액 number>=0","damage_rate":"피해율(F-115 결과) number 0..1","deductible_rate":"자기부담비율 number 0..1"}', 'p.632', 'F-121', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-122', '농업수입감소보험금 (기대수입형)', 'reference_revenue * (damage_rate - deductible_rate)', '{"reference_revenue":"기준수입(F-116 또는 F-117) number>0","damage_rate":"피해율(F-115 결과) number 0..1","deductible_rate":"자기부담비율 number 0..1"}', 'p.631', 'F-122', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-123', '벼 농업수입감소 손해액 (기준가격 ≥ 수확기가격)', '(reference_price - harvest_period_price) * (reference_yield - damage_yield)', '{"reference_price":"기준가격 number>0","harvest_period_price":"수확기가격 number>=0","reference_yield":"평년수확량 number>0","damage_yield":"피해수확량 number>=0"}', 'p.633', 'F-123', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-124', '벼 농업수입감소 손해액 (대안)', 'reference_price * damage_yield', '{"reference_price":"기준가격 number>0","damage_yield":"피해수확량 number>=0"}', 'p.633', 'F-124', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-125', '인삼 단위면적당 조사수확량', 'total_yield / harvest_area_at_time', '{"total_yield":"총수확량 number>=0","harvest_area_at_time":"금차수확면적(=금차수확칸수 × 조사칸넓이) number>0"}', 'p.574', 'F-125', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-126', '인삼 단위면적당 미보상감수량', '(per_year_reference_yield - per_area_actual_yield) * uncovered_ratio', '{"per_year_reference_yield":"연근별 기준수확량 number>0","per_area_actual_yield":"단위면적당 조사수확량(F-125 결과) number>=0","uncovered_ratio":"미보상비율 number 0..1"}', 'p.574', 'F-126', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-127', '인삼 수확량 산정 (단위면적당)', 'per_area_actual_yield + per_area_uncovered_loss', '{"per_area_actual_yield":"단위면적당 조사수확량(F-125 결과) number>=0","per_area_uncovered_loss":"단위면적당 미보상감수량(F-126 결과) number>=0"}', 'p.574', 'F-127', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-128', '해가림시설 자기부담금 (10/100/10%)', 'max(min(loss_amount * 0.10, 1000000), 100000)', '{"loss_amount":"손해액 number>=0"}', 'p.575', 'F-128', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-129', '수입감소 자기부담비율별 경작불능보험금 (밭작물)', 'insurance_amount * coverage_rate', '{"insurance_amount":"보험가입금액 number>=0","coverage_rate":"자기부담비율별 보장비율 (밭작물별 약관) number 0..1"}', 'p.630', 'F-129', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-130', '잔존물 제거비용 한도', 'min(removal_cost, loss_amount * 0.10)', '{"removal_cost":"잔존물 제거비용 number>=0","loss_amount":"손해액 number>=0"}', 'p.585', 'F-130', 2026);

